  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals works with an invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 5 * 8500 + 10 * 9500;
  assert.equal(totals.subtotal, subtotal);
  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  // total = subtotal - discount + vat
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

