  const amountAfterDiscount = lineAmountAfterDiscount(line);
  const lineTotal = 10 * 8500; // 85000
  const discount = lineTotal * 10 / 100; // 8500
  const expected = lineTotal - Math.round(discount);
  assert.equal(amountAfterDiscount, expected);
});

test('lineVat calculates correctly', () => {
